# GENERATED by build.ps1 - edit src/ instead.
& {
# Parses, edits and serializes blacklist.filter text. Pure: no I/O.
# Values keep the spelling found in the file, so daemon-escaped items survive a merge.

function New-FilterSection {
    param([string]$Name)
    return @{ Name = $Name; Entries = (New-Object System.Collections.ArrayList) }
}

function ConvertFrom-FilterText {
    param([string]$Text)

    $sections = New-Object System.Collections.ArrayList
    $current = $null
    $lines = [regex]::Split($Text, '\r?\n')

    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i].Trim()
        if ($line -eq '') { continue }

        if ($line -match '^\[(.+)\]$') {
            $current = New-FilterSection -Name $Matches[1]
            [void]$sections.Add($current)
            continue
        }

        if ($null -eq $current) {
            $current = New-FilterSection -Name ''
            [void]$sections.Add($current)
        }

        if ($line -notmatch '^([^=\s]+)\s*=\s*(.*)$') {
            [void]$current.Entries.Add(@{ Key = $null; Raw = $line })
            continue
        }

        $key = $Matches[1]
        $value = $Matches[2]
        while ($value.TrimEnd().EndsWith(',') -and ($i + 1) -lt $lines.Count) {
            $i++
            $value = $value.TrimEnd() + ' ' + $lines[$i].Trim()
        }

        if ($value.StartsWith('"')) {
            $values = New-Object System.Collections.ArrayList
            foreach ($match in [regex]::Matches($value, '"((?:[^"\\]|\\.)*)"')) {
                [void]$values.Add($match.Groups[1].Value)
            }
            [void]$current.Entries.Add(@{ Key = $key; IsList = $true; Values = $values })
        }
        else {
            [void]$current.Entries.Add(@{ Key = $key; IsList = $false; Raw = $value })
        }
    }

    return @{ Sections = $sections }
}

function ConvertTo-FilterText {
    param([hashtable]$Document)

    $output = New-Object System.Collections.ArrayList
    foreach ($section in $Document.Sections) {
        if ($section.Name -ne '') { [void]$output.Add("[$($section.Name)]") }
        foreach ($entry in $section.Entries) {
            if ($null -eq $entry.Key) {
                [void]$output.Add($entry.Raw)
            }
            elseif ($entry.IsList) {
                $quoted = @($entry.Values | ForEach-Object { '"' + $_ + '"' })
                [void]$output.Add("$($entry.Key) = $($quoted -join ', ')")
            }
            else {
                [void]$output.Add("$($entry.Key) = $($entry.Raw)")
            }
        }
        [void]$output.Add('')
    }
    return ($output -join "`r`n")
}

# Canonical form for comparing the repo spelling with the daemon spelling,
# e.g. "$Recycle.Bin" with "\x24Recycle.Bin" and "@tmp" with "/\x40tmp".
function Get-NormalizedFilterValue {
    param([string]$Value, [string]$Key)

    $decoded = [regex]::Replace($Value, '\\(x[0-9a-fA-F]{2}|.)', {
            param($match)
            $code = $match.Groups[1].Value
            if ($code.Length -eq 3) { return [string][char][Convert]::ToInt32($code.Substring(1), 16) }
            switch -CaseSensitive ($code) {
                'r' { return "`r" }
                'n' { return "`n" }
                't' { return "`t" }
                default { return $code }
            }
        })

    if ($Key -eq 'black_dir_prefix' -and $decoded.StartsWith('/')) { $decoded = $decoded.Substring(1) }
    return $decoded.ToLowerInvariant()
}

function Get-FilterSection {
    param([hashtable]$Document, [string]$Name, [switch]$Create)

    foreach ($section in $Document.Sections) {
        if ($section.Name -eq $Name) { return $section }
    }
    if (-not $Create) { return $null }

    $section = New-FilterSection -Name $Name
    [void]$Document.Sections.Add($section)
    return $section
}

function Get-FilterValues {
    param([hashtable]$Document, [string]$Section, [string]$Key)

    $found = Get-FilterSection -Document $Document -Name $Section
    if ($null -eq $found) { return @() }
    foreach ($entry in $found.Entries) {
        if ($entry.Key -eq $Key -and $entry.IsList) { return @($entry.Values) }
    }
    return @()
}

# Appends values that are not present yet. Never removes or rewrites an existing value.
function Add-FilterValues {
    param([hashtable]$Document, [string]$Section, [string]$Key, [string[]]$Values)

    $target = Get-FilterSection -Document $Document -Name $Section -Create
    $entry = $null
    foreach ($candidate in $target.Entries) {
        if ($candidate.Key -eq $Key) { $entry = $candidate; break }
    }

    if ($null -eq $entry) {
        $entry = @{ Key = $Key; IsList = $true; Values = (New-Object System.Collections.ArrayList) }
        [void]$target.Entries.Add($entry)
    }
    elseif (-not $entry.IsList) {
        if ($entry.Raw -ne '') { throw "Cannot add to non-list key [$Section] $Key" }
        $entry.IsList = $true
        $entry.Values = New-Object System.Collections.ArrayList
    }

    $known = @{}
    foreach ($value in $entry.Values) { $known[(Get-NormalizedFilterValue -Value $value -Key $Key)] = $true }
    foreach ($value in $Values) {
        $normalized = Get-NormalizedFilterValue -Value $value -Key $Key
        if (-not $known.ContainsKey($normalized)) {
            [void]$entry.Values.Add($value)
            $known[$normalized] = $true
        }
    }
}

function Get-FilterValueMap {
    param([hashtable]$Document)

    $map = @{}
    foreach ($section in $Document.Sections) {
        foreach ($entry in $section.Entries) {
            if ($null -eq $entry.Key) { continue }
            $id = "$($section.Name)|$($entry.Key)"
            if (-not $map.ContainsKey($id)) { $map[$id] = @{} }
            $values = if ($entry.IsList) { @($entry.Values) } elseif ($entry.Raw -ne '') { @($entry.Raw) } else { @() }
            foreach ($value in $values) {
                $map[$id][(Get-NormalizedFilterValue -Value $value -Key $entry.Key)] = $value
            }
        }
    }
    return $map
}

# Value-level difference, so a spelling change alone is not reported.
function Get-FilterDiff {
    param([hashtable]$Before, [hashtable]$After)

    $beforeMap = Get-FilterValueMap -Document $Before
    $afterMap = Get-FilterValueMap -Document $After
    $changes = New-Object System.Collections.ArrayList

    foreach ($id in @(@($beforeMap.Keys) + @($afterMap.Keys) | Sort-Object -Unique)) {
        $old = if ($beforeMap.ContainsKey($id)) { $beforeMap[$id] } else { @{} }
        $new = if ($afterMap.ContainsKey($id)) { $afterMap[$id] } else { @{} }
        $added = @($new.Keys | Where-Object { -not $old.ContainsKey($_) } | ForEach-Object { $new[$_] } | Sort-Object)
        $removed = @($old.Keys | Where-Object { -not $new.ContainsKey($_) } | ForEach-Object { $old[$_] } | Sort-Object)
        if ($added.Count -gt 0 -or $removed.Count -gt 0) {
            $parts = $id.Split('|')
            [void]$changes.Add(@{ Section = $parts[0]; Key = $parts[1]; Added = $added; Removed = $removed })
        }
    }
    return , @($changes)
}

# The selectable rule groups. Display names live in the web UI, keyed by Id.
# gitPointerFile is off by default until the daemon is confirmed to keep [File] black_name.

function Get-RuleCatalog {
    return @(
        @{ Id = 'git'; Default = $true; Directories = @('.git'); FileNames = @(); FileSuffixes = @() }
        @{ Id = 'worktrees'; Default = $true; Directories = @('worktrees', '.worktrees'); FileNames = @(); FileSuffixes = @() }
        @{ Id = 'gitPointerFile'; Default = $false; Directories = @(); FileNames = @('.git'); FileSuffixes = @() }
        @{ Id = 'fankeel'; Default = $true; Directories = @('.fankeel'); FileNames = @(); FileSuffixes = @() }
        @{ Id = 'node'; Default = $true; Directories = @('node_modules', '.node-gyp'); FileNames = @(); FileSuffixes = @() }
        @{ Id = 'python'; Default = $true; Directories = @('.venv', 'venv', '__pycache__', '.pytest_cache', '.ruff_cache', '.mypy_cache'); FileNames = @(); FileSuffixes = @('.pyc', '.pyo') }
        @{ Id = 'build'; Default = $true; Directories = @('dist', 'build', '.next', '.svelte-kit', '.turbo', '.vite', '.parcel-cache'); FileNames = @(); FileSuffixes = @() }
        @{ Id = 'tools'; Default = $true; Directories = @('.cache', '.gradle', '.idea', 'coverage', '.playwright-mcp'); FileNames = @(); FileSuffixes = @() }
        @{ Id = 'system'; Default = $true; Directories = @('@tmp', '@eaDir', '.SynologyWorkingDirectory', '#recycle', 'desktop.ini', '.ds_store', 'Icon\r', 'thumbs.db', '$Recycle.Bin', '@sharebin', 'System Volume Information', 'Program Files', 'Program Files (x86)', 'ProgramData', '#snapshot'); FileNames = @(); FileSuffixes = @('tmp', 'temp', '.swp', '.lnk', '.pst') }
    )
}

function Add-RuleGroup {
    param([hashtable]$Document, [hashtable]$Group)

    if ($Group.Directories.Count -gt 0) { Add-FilterValues -Document $Document -Section 'Directory' -Key 'black_name' -Values $Group.Directories }
    if ($Group.FileNames.Count -gt 0) { Add-FilterValues -Document $Document -Section 'File' -Key 'black_name' -Values $Group.FileNames }
    if ($Group.FileSuffixes.Count -gt 0) { Add-FilterValues -Document $Document -Section 'File' -Key 'black_suffix' -Values $Group.FileSuffixes }
}

function Test-RuleGroupApplied {
    param([hashtable]$Document, [hashtable]$Group)

    $checks = @(
        @{ Section = 'Directory'; Key = 'black_name'; Wanted = $Group.Directories }
        @{ Section = 'File'; Key = 'black_name'; Wanted = $Group.FileNames }
        @{ Section = 'File'; Key = 'black_suffix'; Wanted = $Group.FileSuffixes }
    )
    foreach ($check in $checks) {
        $present = @(Get-FilterValues -Document $Document -Section $check.Section -Key $check.Key |
                ForEach-Object { Get-NormalizedFilterValue -Value $_ -Key $check.Key })
        foreach ($wanted in $check.Wanted) {
            if ($present -notcontains (Get-NormalizedFilterValue -Value $wanted -Key $check.Key)) { return $false }
        }
    }
    return $true
}

# Use cases. All side effects go through the $Ports hashtable of script blocks:
#   ListSessions, ReadText, WriteText, CreateBackup, ListBackups, RestoreSource,
#   GetRunningProcesses, ResolveRoots, IsInstalled, GetStamp, TemplateText

function New-UseCaseResult {
    param([int]$Status = 200, [hashtable]$Body = @{})
    return @{ Status = $Status; Body = $Body }
}

function New-UseCaseError {
    param([int]$Status, [string]$Code)
    return New-UseCaseResult -Status $Status -Body @{ error = $Code }
}

function Get-RunningRefusal {
    param([hashtable]$Ports)
    $running = @(& $Ports.GetRunningProcesses)
    if ($running.Count -eq 0) { return $null }
    return New-UseCaseResult -Status 409 -Body @{ error = 'synology_running'; running = $running }
}

function Get-RunningState {
    param([hashtable]$Ports)
    return New-UseCaseResult -Body @{ running = @(& $Ports.GetRunningProcesses) }
}

function Invoke-Scan {
    param([hashtable]$Ports)

    $catalog = @(Get-RuleCatalog)
    $sessions = @(& $Ports.ListSessions)
    $roots = & $Ports.ResolveRoots @($sessions | ForEach-Object { $_.Id })

    $resultSessions = @(foreach ($session in $sessions) {
            $document = ConvertFrom-FilterText -Text (& $Ports.ReadText $session.FilterPath)
            $current = New-Object System.Collections.ArrayList
            foreach ($section in $document.Sections) {
                foreach ($entry in $section.Entries) {
                    if ($null -eq $entry.Key -or -not $entry.IsList) { continue }
                    [void]$current.Add(@{ section = $section.Name; key = $entry.Key; values = @($entry.Values) })
                }
            }
            @{
                id           = $session.Id
                filterPath   = $session.FilterPath
                root         = $roots[$session.Id]
                missing      = @($catalog | Where-Object { -not (Test-RuleGroupApplied -Document $document -Group $_) } | ForEach-Object { $_.Id })
                current      = @($current)
                backups      = @(& $Ports.ListBackups $session.FilterPath)
            }
        })

    return New-UseCaseResult -Body @{
        installed = [bool](& $Ports.IsInstalled)
        running   = @(& $Ports.GetRunningProcesses)
        sessions  = $resultSessions
        groups    = @($catalog | ForEach-Object {
                @{ id = $_.Id; default = $_.Default; directories = $_.Directories; fileNames = $_.FileNames; fileSuffixes = $_.FileSuffixes }
            })
    }
}

# Resolves request values against what the tool found itself; returns an error result or a plan.
function Resolve-ChangeRequest {
    param([hashtable]$Ports, $Request)

    if (@('merge', 'overwrite') -notcontains $Request.mode) { return @{ Error = (New-UseCaseError -Status 400 -Code 'bad_mode') } }

    $known = @{}
    foreach ($session in @(& $Ports.ListSessions)) { $known[$session.Id] = $session }
    $wantedSessions = @($Request.sessions)
    if ($wantedSessions.Count -eq 0) { return @{ Error = (New-UseCaseError -Status 400 -Code 'no_session') } }
    foreach ($id in $wantedSessions) {
        if (-not $known.ContainsKey([string]$id)) { return @{ Error = (New-UseCaseError -Status 400 -Code 'unknown_session') } }
    }

    $catalog = @{}
    foreach ($group in @(Get-RuleCatalog)) { $catalog[$group.Id] = $group }
    $groups = @()
    if ($Request.mode -eq 'merge') {
        $wantedGroups = @($Request.groups)
        if ($wantedGroups.Count -eq 0) { return @{ Error = (New-UseCaseError -Status 400 -Code 'no_group') } }
        foreach ($id in $wantedGroups) {
            if (-not $catalog.ContainsKey([string]$id)) { return @{ Error = (New-UseCaseError -Status 400 -Code 'unknown_group') } }
            $groups += $catalog[[string]$id]
        }
    }

    $plans = @(foreach ($id in $wantedSessions) {
            $session = $known[[string]$id]
            $beforeText = & $Ports.ReadText $session.FilterPath
            $before = ConvertFrom-FilterText -Text $beforeText
            if ($Request.mode -eq 'overwrite') {
                $afterText = $Ports.TemplateText
                $after = ConvertFrom-FilterText -Text $afterText
            }
            else {
                $after = ConvertFrom-FilterText -Text $beforeText
                foreach ($group in $groups) { Add-RuleGroup -Document $after -Group $group }
                $afterText = ConvertTo-FilterText -Document $after
            }
            @{ Session = $session; AfterText = $afterText; Changes = (Get-FilterDiff -Before $before -After $after) }
        })
    return @{ Plans = $plans }
}

function ConvertTo-ChangeView {
    param($Changes)
    return @($Changes | ForEach-Object { @{ section = $_.Section; key = $_.Key; added = $_.Added; removed = $_.Removed } })
}

function Invoke-Preview {
    param([hashtable]$Ports, $Request)

    $resolved = Resolve-ChangeRequest -Ports $Ports -Request $Request
    if ($resolved.Error) { return $resolved.Error }
    return New-UseCaseResult -Body @{
        previews = @($resolved.Plans | ForEach-Object { @{ id = $_.Session.Id; changes = (ConvertTo-ChangeView $_.Changes) } })
    }
}

function Invoke-Apply {
    param([hashtable]$Ports, $Request)

    $resolved = Resolve-ChangeRequest -Ports $Ports -Request $Request
    if ($resolved.Error) { return $resolved.Error }
    $refusal = Get-RunningRefusal -Ports $Ports
    if ($refusal) { return $refusal }

    $stamp = & $Ports.GetStamp
    $results = @(foreach ($plan in $resolved.Plans) {
            try {
                if ($plan.Changes.Count -eq 0) {
                    @{ id = $plan.Session.Id; ok = $true; unchanged = $true }
                    continue
                }
                $backup = & $Ports.CreateBackup $plan.Session.FilterPath $stamp
                & $Ports.WriteText $plan.Session.FilterPath $plan.AfterText
                @{ id = $plan.Session.Id; ok = $true; backup = $backup }
            }
            catch {
                @{ id = $plan.Session.Id; ok = $false; message = $_.Exception.Message }
            }
        })
    return New-UseCaseResult -Body @{ results = $results }
}

function Invoke-Rollback {
    param([hashtable]$Ports, $Request)

    $session = @(& $Ports.ListSessions) | Where-Object { $_.Id -eq [string]$Request.session } | Select-Object -First 1
    if ($null -eq $session) { return New-UseCaseError -Status 400 -Code 'unknown_session' }
    $backups = @(& $Ports.ListBackups $session.FilterPath)
    if ($backups -cnotcontains [string]$Request.backup) { return New-UseCaseError -Status 400 -Code 'unknown_backup' }
    $refusal = Get-RunningRefusal -Ports $Ports
    if ($refusal) { return $refusal }

    $text = & $Ports.RestoreSource $session.FilterPath $Request.backup
    $safety = & $Ports.CreateBackup $session.FilterPath (& $Ports.GetStamp)
    & $Ports.WriteText $session.FilterPath $text
    return New-UseCaseResult -Body @{ id = $session.Id; backup = $safety }
}

# Real implementations of the use-case ports: the file system, processes and Synology logs.

function Get-SynologyHome {
    if ($env:SYNOLOGY_FILTER_HOME) { return $env:SYNOLOGY_FILTER_HOME }
    return (Join-Path $env:LOCALAPPDATA 'SynologyDrive')
}

function Get-SessionFilters {
    param([string]$SynologyHome)

    $pattern = Join-Path $SynologyHome 'data\session\*\conf\blacklist.filter'
    return @(Get-ChildItem -Path $pattern -ErrorAction SilentlyContinue | ForEach-Object {
            $id = $_.Directory.Parent.Name
            if ($id -match '^\d+$') { @{ Id = $id; FilterPath = $_.FullName } }
        } | Sort-Object { [int]$_.Id })
}

# Daemon log lines carry no session id next to local paths, so a root is only
# attributed when the logs show a single active session. Anything else stays unknown.
function Resolve-SessionRoots {
    param([string]$SynologyHome, [string[]]$SessionIds)

    $roots = @{}
    foreach ($id in $SessionIds) { $roots[$id] = $null }

    $logs = @(Get-ChildItem -Path (Join-Path $SynologyHome 'log\daemon.log*') -ErrorAction SilentlyContinue |
            Sort-Object LastWriteTime -Descending | Select-Object -First 5)
    if ($logs.Count -eq 0) { return $roots }

    try {
        $active = @{}
        $candidates = @{}
        $pattern = "Session \((\d+)\)|'([A-Za-z]:\\[^'/]*)/"
        foreach ($hit in (Select-String -Path $logs.FullName -Pattern $pattern -AllMatches -ErrorAction Stop)) {
            foreach ($match in $hit.Matches) {
                if ($match.Groups[1].Success) { $active[$match.Groups[1].Value] = $true }
                if ($match.Groups[2].Success) { $candidates[$match.Groups[2].Value] = 1 + [int]$candidates[$match.Groups[2].Value] }
            }
        }
        if ($active.Count -ne 1) { return $roots }

        $sessionId = @($active.Keys)[0]
        if (-not $roots.ContainsKey($sessionId)) { return $roots }
        $ranked = $candidates.GetEnumerator() | Sort-Object Value -Descending
        foreach ($candidate in $ranked) {
            if (Test-Path -LiteralPath (Join-Path $candidate.Key '.SynologyWorkingDirectory')) {
                $roots[$sessionId] = $candidate.Key
                break
            }
        }
    }
    catch {
        Write-Verbose "Cannot read Synology logs: $($_.Exception.Message)"
    }
    return $roots
}

function Write-TextAtomic {
    param([string]$Path, [string]$Text)

    $temporary = "$Path.writing-$([guid]::NewGuid().ToString('N'))"
    try {
        [IO.File]::WriteAllText($temporary, $Text, (New-Object System.Text.UTF8Encoding($false)))
        # PowerShell turns $null into '' for string arguments; Replace needs a real null.
        [IO.File]::Replace($temporary, $Path, [NullString]::Value)
    }
    finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force }
    }
}

function New-SynologyPorts {
    param([string]$SynologyHome, [string]$TemplateText)

    $rootCache = @{ Value = $null }
    # GetNewClosure blocks cannot see functions from the bundle scope, so capture them.
    $findSessions = ${function:Get-SessionFilters}
    $findRoots = ${function:Resolve-SessionRoots}

    return @{
        TemplateText        = $TemplateText
        IsInstalled         = { Test-Path -LiteralPath (Join-Path $SynologyHome 'data\session') }.GetNewClosure()
        ListSessions        = { & $findSessions -SynologyHome $SynologyHome }.GetNewClosure()
        ResolveRoots        = {
            param($ids)
            if ($null -eq $rootCache.Value) { $rootCache.Value = & $findRoots -SynologyHome $SynologyHome -SessionIds $ids }
            return $rootCache.Value
        }.GetNewClosure()
        ReadText            = { param($path) return [IO.File]::ReadAllText($path, [Text.Encoding]::UTF8) }
        WriteText           = { param($path, $text) Write-TextAtomic -Path $path -Text $text }
        GetStamp            = { return (Get-Date -Format 'yyyyMMdd-HHmmss') }
        CreateBackup        = {
            param($path, $stamp)
            $backup = "$path.bak-$stamp"
            [IO.File]::Copy($path, $backup, $false)
            return (Split-Path -Leaf $backup)
        }
        ListBackups         = {
            param($path)
            return @(Get-ChildItem -LiteralPath (Split-Path -Parent $path) -Filter 'blacklist.filter.bak-*' |
                    Sort-Object Name -Descending | ForEach-Object { $_.Name })
        }
        RestoreSource       = {
            param($path, $backup)
            return [IO.File]::ReadAllText((Join-Path (Split-Path -Parent $path) $backup), [Text.Encoding]::UTF8)
        }
        GetRunningProcesses = {
            return @(Get-Process -Name 'cloud-drive-ui', 'cloud-drive-connect', 'cloud-drive-daemon' -ErrorAction SilentlyContinue |
                    ForEach-Object { $_.ProcessName } | Sort-Object -Unique)
        }
    }
}

# Minimal loopback HTTP server. TcpListener needs no URL ACL or administrator rights.
# Requests are handled one at a time, so a shutdown can never interrupt a write.

function Read-HttpRequest {
    param([System.Net.Sockets.TcpClient]$Client)

    $Client.ReceiveTimeout = 1000
    $stream = $Client.GetStream()
    $stream.ReadTimeout = 1000
    $buffer = New-Object byte[] 8192
    $received = New-Object System.IO.MemoryStream
    $headerEnd = -1

    while ($headerEnd -lt 0) {
        $count = $stream.Read($buffer, 0, $buffer.Length)
        if ($count -le 0) { return $null }
        $received.Write($buffer, 0, $count)
        if ($received.Length -gt 16384) { return $null }
        $headerEnd = ([Text.Encoding]::ASCII.GetString($received.ToArray())).IndexOf("`r`n`r`n")
    }

    $all = $received.ToArray()
    $lines = [Text.Encoding]::ASCII.GetString($all, 0, $headerEnd) -split "`r`n"
    $first = $lines[0] -split ' '
    if ($first.Count -lt 3) { return $null }

    $headers = @{}
    foreach ($line in $lines[1..($lines.Count - 1)]) {
        $separator = $line.IndexOf(':')
        if ($separator -gt 0) { $headers[$line.Substring(0, $separator).ToLowerInvariant()] = $line.Substring($separator + 1).Trim() }
    }

    $length = 0
    if ($headers['content-length'] -and -not [int]::TryParse($headers['content-length'], [ref]$length)) { return $null }
    if ($length -lt 0 -or $length -gt 65536) { return $null }

    $bodyStart = $headerEnd + 4
    while (($received.Length - $bodyStart) -lt $length) {
        $count = $stream.Read($buffer, 0, $buffer.Length)
        if ($count -le 0) { return $null }
        $received.Write($buffer, 0, $count)
    }

    $all = $received.ToArray()
    $parts = $first[1] -split '\?', 2
    return @{
        Method  = $first[0]
        Path    = $parts[0]
        Query   = $(if ($parts.Count -gt 1) { $parts[1] } else { '' })
        Headers = $headers
        Body    = [Text.Encoding]::UTF8.GetString($all, $bodyStart, $length)
    }
}

function Write-HttpResponse {
    param([System.Net.Sockets.TcpClient]$Client, [int]$Status, [string]$ContentType, [string]$Content)

    $body = [Text.Encoding]::UTF8.GetBytes($Content)
    $head = @(
        "HTTP/1.1 $Status Status"
        "Content-Type: $ContentType; charset=utf-8"
        "Content-Length: $($body.Length)"
        'Cache-Control: no-store'
        'Referrer-Policy: no-referrer'
        'X-Content-Type-Options: nosniff'
        "Content-Security-Policy: default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'"
        'Connection: close'
    ) -join "`r`n"
    $bytes = [Text.Encoding]::ASCII.GetBytes("$head`r`n`r`n")
    $stream = $Client.GetStream()
    $stream.Write($bytes, 0, $bytes.Length)
    $stream.Write($body, 0, $body.Length)
    $stream.Flush()
}

function Test-RequestTrusted {
    param([hashtable]$Request, [int]$Port, [string]$Token)

    $authority = "127.0.0.1:$Port"
    if ($Request.Headers['host'] -cne $authority) { return $false }
    if ($Request.Headers['origin'] -and $Request.Headers['origin'] -cne "http://$authority") { return $false }
    if ($Request.Method -eq 'GET' -and $Request.Path -eq '/') { return ($Request.Query -ceq "t=$Token") }
    return ($Request.Headers['x-token'] -ceq $Token)
}

function ConvertTo-JsonText {
    param($Value)
    return (ConvertTo-Json -InputObject $Value -Depth 10 -Compress)
}

function Invoke-ApiRequest {
    param([hashtable]$Ports, [hashtable]$Request)

    $payload = $null
    if ($Request.Body) { $payload = ConvertFrom-Json -InputObject $Request.Body }

    switch ($Request.Path) {
        '/api/scan' { return Invoke-Scan -Ports $Ports }
        '/api/running' { return Get-RunningState -Ports $Ports }
        '/api/preview' { return Invoke-Preview -Ports $Ports -Request $payload }
        '/api/apply' { return Invoke-Apply -Ports $Ports -Request $payload }
        '/api/rollback' { return Invoke-Rollback -Ports $Ports -Request $payload }
        default { return New-UseCaseError -Status 404 -Code 'not_found' }
    }
}

function Start-ToolServer {
    param([hashtable]$Ports, [string]$Html, [int]$BeatTimeoutSeconds = 150, [int]$IdleTimeoutSeconds = 900)

    $random = New-Object byte[] 24
    $generator = [Security.Cryptography.RandomNumberGenerator]::Create()
    $generator.GetBytes($random)
    $generator.Dispose()
    $token = ([BitConverter]::ToString($random) -replace '-', '').ToLowerInvariant()

    $listener = New-Object System.Net.Sockets.TcpListener ([Net.IPAddress]::Loopback, 0)
    $listener.Start()
    $port = $listener.LocalEndpoint.Port
    $url = "http://127.0.0.1:$port/?t=$token"

    Write-Output "Synology Drive Filter Tool: $url"
    Write-Output 'Keep this window open. It closes itself when you press Finish in the browser.'
    if (-not $env:SYNOLOGY_FILTER_NO_BROWSER) { Start-Process $url }

    $lastActivity = Get-Date
    $lastBeat = $null
    $stop = $false

    try {
        while (-not $stop) {
            if (-not $listener.Pending()) {
                $now = Get-Date
                if ($lastBeat -and ($now - $lastBeat).TotalSeconds -gt $BeatTimeoutSeconds) { Write-Output 'Browser closed. Stopping.'; break }
                if (($now - $lastActivity).TotalSeconds -gt $IdleTimeoutSeconds) { Write-Output 'Idle timeout. Stopping.'; break }
                Start-Sleep -Milliseconds 100
                continue
            }

            $client = $listener.AcceptTcpClient()
            try {
                $request = Read-HttpRequest -Client $client
                if ($null -eq $request) { continue }

                if (-not (Test-RequestTrusted -Request $request -Port $port -Token $token)) {
                    Write-HttpResponse -Client $client -Status 403 -ContentType 'application/json' -Content '{"error":"forbidden"}'
                    continue
                }

                if ($request.Method -eq 'GET' -and $request.Path -eq '/') {
                    $lastActivity = Get-Date
                    Write-HttpResponse -Client $client -Status 200 -ContentType 'text/html' -Content $Html
                    continue
                }

                if ($request.Method -ne 'POST') {
                    Write-HttpResponse -Client $client -Status 404 -ContentType 'application/json' -Content '{"error":"not_found"}'
                    continue
                }

                if ($request.Path -eq '/api/heartbeat') {
                    $lastBeat = Get-Date
                    Write-HttpResponse -Client $client -Status 200 -ContentType 'application/json' -Content '{}'
                    continue
                }

                if ($request.Path -eq '/api/shutdown') {
                    Write-HttpResponse -Client $client -Status 200 -ContentType 'application/json' -Content '{}'
                    $stop = $true
                    continue
                }

                $lastActivity = Get-Date
                $result = try {
                    Invoke-ApiRequest -Ports $Ports -Request $request
                }
                catch {
                    Write-Warning $_.Exception.Message
                    New-UseCaseResult -Status 500 -Body @{ error = 'internal'; message = $_.Exception.Message }
                }
                Write-HttpResponse -Client $client -Status $result.Status -ContentType 'application/json' -Content (ConvertTo-JsonText $result.Body)
            }
            catch [System.IO.IOException] {
                Write-Verbose 'Client disconnected or sent nothing.'
            }
            finally {
                $client.Close()
            }
        }
    }
    finally {
        $listener.Stop()
    }
    Write-Output 'Stopped.'
}

# Composition root. Get-EmbeddedAsset is generated by build.ps1.

function Start-SynologyFilterTool {
    $ErrorActionPreference = 'Stop'
    $ports = New-SynologyPorts -SynologyHome (Get-SynologyHome) -TemplateText (Get-EmbeddedAsset -Name 'template')
    Start-ToolServer -Ports $ports -Html (Get-EmbeddedAsset -Name 'web')
}

function Get-EmbeddedAsset {
    param([string]$Name)
    $data = @{ web = ''; template = '' }
    return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($data[$Name]))
}
Start-SynologyFilterTool
}
